def script_text(name):
    b = EPS[name]["beats"]; parts = []
    for i, k in enumerate(ORDER):
        if k == "cta":
            parts.append("[warm] " + CTA); continue
        tag, txt = b[k]
        parts.append((f"[{tag}] " if tag else "") + txt)
    return " [long pause] ".join(parts)

def text_dict(name):
    """Plain TEXT dict for ep_<name>.py (tags removed)."""
    import re
    d = {k: re.sub(r"\s*\[[a-z ]+\]\s*", " ", EPS[name]["beats"][k][1]).strip() for k in ORDER if k != "cta"}
    d["cta"] = CTA
    return d

if __name__ == "__main__":
    import os
    os.makedirs("scripts", exist_ok=True)
    tot = 0
    for n in EPS:
        s = script_text(n); tot += len(s)
        open(f"scripts/{n}_script.txt", "w").write(s + "\n")
        print(f"EP{EPS[n]['ep']:>2} {n:<11} {len(s):>5} chars")
    print("TOTAL", tot)
